-- 外研社七下(wy7B) 词表灌库 · junior_vocab · Aaron service role 跑 · 幂等(先 DELETE by publisher+volume 再 INSERT)
-- publisher=junior_fltrp / volume=wy7B / grade=7 / unit∈{U1..U6} · 381词 · 短语 pos/phonetic=NULL · freq_rank=课本顺序 · IPA照抄视觉读出
-- ★DELETE 带 publisher='junior_fltrp' AND volume='wy7B',绝不动人教/wy7A 行★
BEGIN;
DELETE FROM public.junior_vocab WHERE publisher='junior_fltrp' AND volume='wy7B';

-- 断言
DO $$
DECLARE tot int; c int; polluted int; nulls int; dup int;
BEGIN
  SELECT count(*) INTO tot FROM public.junior_vocab WHERE publisher='junior_fltrp' AND volume='wy7B';
  IF tot<>381 THEN RAISE EXCEPTION 'total=% 期望381', tot; END IF;
  SELECT count(*) INTO c FROM public.junior_vocab WHERE publisher='junior_fltrp' AND volume='wy7B' AND unit='U1'; IF c<>76 THEN RAISE EXCEPTION 'U1=% 期望76', c; END IF;
  SELECT count(*) INTO c FROM public.junior_vocab WHERE publisher='junior_fltrp' AND volume='wy7B' AND unit='U2'; IF c<>81 THEN RAISE EXCEPTION 'U2=% 期望81', c; END IF;
  SELECT count(*) INTO c FROM public.junior_vocab WHERE publisher='junior_fltrp' AND volume='wy7B' AND unit='U3'; IF c<>75 THEN RAISE EXCEPTION 'U3=% 期望75', c; END IF;
  SELECT count(*) INTO c FROM public.junior_vocab WHERE publisher='junior_fltrp' AND volume='wy7B' AND unit='U4'; IF c<>60 THEN RAISE EXCEPTION 'U4=% 期望60', c; END IF;
  SELECT count(*) INTO c FROM public.junior_vocab WHERE publisher='junior_fltrp' AND volume='wy7B' AND unit='U5'; IF c<>44 THEN RAISE EXCEPTION 'U5=% 期望44', c; END IF;
  SELECT count(*) INTO c FROM public.junior_vocab WHERE publisher='junior_fltrp' AND volume='wy7B' AND unit='U6'; IF c<>45 THEN RAISE EXCEPTION 'U6=% 期望45', c; END IF;
  SELECT count(*) INTO polluted FROM public.junior_vocab WHERE volume='wy7B' AND publisher<>'junior_fltrp';
  IF polluted<>0 THEN RAISE EXCEPTION 'pep/wy7A 行被污染=%', polluted; END IF;
  SELECT count(*) INTO nulls FROM public.junior_vocab WHERE publisher='junior_fltrp' AND volume='wy7B' AND (word IS NULL OR meaning_cn IS NULL);
  IF nulls<>0 THEN RAISE EXCEPTION 'word/meaning 空=%', nulls; END IF;
  SELECT count(*) INTO dup FROM (SELECT word_id FROM public.junior_vocab WHERE publisher='junior_fltrp' AND volume='wy7B' GROUP BY word_id HAVING count(*)>1) t;
  IF dup<>0 THEN RAISE EXCEPTION 'word_id 重复=%', dup; END IF;
  RAISE NOTICE 'OK: wy7B 词表 % 条 · 六单元计数达标 · 无污染/空值/重复', tot;
END $$;

COMMIT;
-- 复核:各单元词数
SELECT unit, count(*) FROM public.junior_vocab WHERE publisher='junior_fltrp' AND volume='wy7B' GROUP BY unit ORDER BY min(freq_rank);